if(document.modelContext?.registerTool){const controller=new AbortController();for(const tool of [{name:'search_cakes',title:'Buscar kekes',description:'Buscar productos existentes del catálogo, sin modificar el carrito.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({query})=>{if(typeof query!=='string')throw Error('Consulta inválida');return products.filter(p=>norm(p.name+' '+p.category).includes(norm(query))).map(p=>({id:p.id,name:p.name,basePrice:p.basePrice,url:'/productos/'+p.slug}))}},{name:'add_cake_to_cart',title:'Agregar keke al carrito',description:'Agrega un producto existente al carrito global con tamaño pequeño y decoración clásica; no realiza un pedido ni un pago.',inputSchema:{type:'object',properties:{productId:{type:'string'},quantity:{type:'integer',minimum:1,maximum:99}},required:['productId','quantity'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({productId,quantity})=>{if(!Number.isInteger(quantity)||quantity<1||quantity>99)throw Error('Cantidad inválida');const item=addItem(productId,{quantity});toast('Producto agregado al carrito',true);if(routePath()==='/carrito')render();return {item,total:totals().total}}}])try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true})}


